#!/usr/bin/env bash
# Generates deploy/prod/<service>/Dockerfile from the root Dockerfile.
#
# Some CI platforms build exactly one Dockerfile path and expose no build
# args, so each service needs a file whose SERVICE (and WEBUI for the gateway)
# is already defaulted. Those files are mechanical copies of the root
# Dockerfile with two ARG defaults filled in — never hand-edited, so the service
# images cannot drift apart.
#
#   deploy/prod/gen-dockerfiles.sh          rewrite the generated files
#   deploy/prod/gen-dockerfiles.sh --check  exit 1 if any is stale (CI)
set -euo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$repo_root"

# cli is the operator CLI image (./cmd/bnbloc), used by the scheduled
# in-cluster smoke (deploy/k8s smoke CronJob, compose `smoke` service).
services="gateway room realtime activity shareagent relay cli"
check=0
[ "${1:-}" = "--check" ] && check=1

render() {
  local svc="$1" webui="none"
  [ "$svc" = "gateway" ] && webui="full"
  # Both substitutions must hit exactly one line each, or the root Dockerfile
  # changed shape and this generator must be updated with it.
  for pattern in '^ARG WEBUI=none$' '^ARG SERVICE$'; do
    if [ "$(grep -c "$pattern" Dockerfile)" != "1" ]; then
      echo "gen-dockerfiles: root Dockerfile must contain exactly one line matching $pattern" >&2
      exit 1
    fi
  done
  printf '# GENERATED by deploy/prod/gen-dockerfiles.sh from /Dockerfile — DO NOT EDIT.\n'
  printf '# bnbloc %s image with SERVICE (and WEBUI) defaulted, for CI that builds\n' "$svc"
  printf '# a Dockerfile path with no build args:\n'
  printf '#   docker build -f deploy/prod/%s/Dockerfile -t bnbloc-%s .\n\n' "$svc" "$svc"
  sed -e "s/^ARG WEBUI=none\$/ARG WEBUI=${webui}/" -e "s/^ARG SERVICE\$/ARG SERVICE=${svc}/" Dockerfile
}

stale=""
for svc in $services; do
  out="deploy/prod/${svc}/Dockerfile"
  if [ "$check" = 1 ]; then
    if ! render "$svc" | cmp -s - "$out"; then
      stale="$stale $out"
    fi
  else
    mkdir -p "$(dirname "$out")"
    render "$svc" > "$out"
  fi
done

if [ -n "$stale" ]; then
  echo "gen-dockerfiles: stale generated Dockerfiles:$stale" >&2
  echo "run deploy/prod/gen-dockerfiles.sh and commit the result" >&2
  exit 1
fi
